import sqlite3

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("smart-home")

DB_PATH = "/var/lib/smarthome/registry.db"


@mcp.tool()
def move_device_to_room(device_id: str, target_room: str) -> dict:
    device_id = (device_id or "").strip()
    target_room = (target_room or "").strip().lower()
    if not device_id:
        return {"ok": False, "error": "device_id is required"}
    if not target_room:
        return {"ok": False, "error": "target_room is required"}

    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute("SELECT room FROM devices WHERE id = ?", (device_id,)).fetchone()
        if row is None:
            return {"ok": False, "error": "device not found"}
        if row[0] == target_room:
            return {"ok": False, "error": "device already in that room"}
        exists = conn.execute("SELECT 1 FROM rooms WHERE name = ?", (target_room,)).fetchone()
        if exists is None:
            return {"ok": False, "error": "target room does not exist"}
        conn.execute("UPDATE devices SET room = ? WHERE id = ?", (target_room, device_id))
        conn.commit()
    finally:
        conn.close()
    return {"ok": True, "device_id": device_id, "from": row[0], "to": target_room}

import time

import requests
from agents import function_tool

_LEVELS = {"low", "medium", "high"}


@function_tool
def send_motion_alert_webhook(
    webhook_url: str,
    device_name: str,
    room: str,
    snapshot_url: str = "",
    severity: str = "medium",
) -> str:
    if not webhook_url.startswith("https://"):
        return "error: webhook_url must use https"
    sev = severity.lower()
    if sev not in _LEVELS:
        return "error: severity must be low, medium or high"

    body = {
        "event": "motion_detected",
        "device": device_name,
        "room": room,
        "severity": sev,
        "ts": int(time.time()),
    }
    if snapshot_url:
        body["snapshot"] = snapshot_url

    hdr = {"Content-Type": "application/json", "User-Agent": "home-hub/1.0"}
    try:
        r = requests.post(webhook_url, json=body, headers=hdr, timeout=10)
    except requests.RequestException as e:
        return f"error: request failed: {e}"

    if r.status_code >= 400:
        return f"error: webhook returned {r.status_code}"
    return f"alert sent for {device_name} in {room} (status {r.status_code})"
